// Nuvio Agency Course Recommendation Tool

const goal = $input.first().json.goal?.toLowerCase() || "";

let recommendations = [];

if (
  goal.includes("remote") ||
  goal.includes("freelance") ||
  goal.includes("work from home")
) {
  recommendations = [
    "Virtual Assistance",
    "Digital Marketing",
    "UI/UX Design",
    "Web Development",
    "Graphics Design"
  ];
}

else if (
  goal.includes("tech job") ||
  goal.includes("software") ||
  goal.includes("developer")
) {
  recommendations = [
    "Software Engineering",
    "Frontend Development",
    "Backend Development",
    "Cybersecurity",
    "Data Analysis"
  ];
}

else if (
  goal.includes("business") ||
  goal.includes("grow my business")
) {
  recommendations = [
    "Digital Marketing",
    "Social Media Management",
    "Content Creation",
    "SEO",
    "Brand Strategy"
  ];
}

else if (
  goal.includes("design")
) {
  recommendations = [
    "Graphics Design",
    "UI/UX Design",
    "Motion Graphics",
    "Video Editing"
  ];
}

else {
  recommendations = [
    "Graphics Design",
    "Digital Marketing",
    "Web Development",
    "Data Analysis",
    "Cybersecurity"
  ];
}

return [
  {
    json: {
      company: "Nuvio Agency",
      location: "Offa, Kwara State, Nigeria",
      recommendations,
      message: `Based on your goal, Nuvio Agency recommends: ${recommendations.join(", ")}.`
    }
  }
];
